 @Test void customerLifecycleNumberingFilteringAndOptimisticLocking()throws Exception{UUID c=customer(false);mvc.perform(post("/api/v1/customers/"+c+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));mvc.perform(get("/api/v1/customers?status=ACTIVE&q=acme&sort=name").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].customerNumber").value(org.hamcrest.Matchers.matchesPattern("CUS-[0-9]{6}")));mvc.perform(patch("/api/v1/customers/"+c).with(token()).contentType("application/json").content(customerJson(0))).andExpect(status().isConflict());}
